python -c "
import pandas as pd,numpy as np
df=pd.read_parquet('equation.parquet'); a=np.array(df.iloc[0]['training_set'].tolist())
y=a[:,0]; t=a[:,1]; P=a[:,2]
def feat(t,P,dt,dP):
    cols=[]
    for i in range(dt+1):
        for j in range(dP+1):
            cols.append((t**i)*(P**j))
    return np.column_stack(cols)
for dt,dP in [(1,2),(2,2),(2,3),(3,3)]:
    A=feat(t,P,dt,dP); c,*_=np.linalg.lstsq(A,y,rcond=None); r=y-A@c
    print(dt,dP,'mse',np.mean(r**2))
"
